"""Worker-owned dashboard, shared notification count, native install invocation and central Aura popup."""
import asyncio,json
from playwright.async_api import async_playwright
HOST='http://127.0.0.1:8010'
async def main():
 async with async_playwright() as pw:
  b=await pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);ctx=await b.new_context(viewport={'width':1440,'height':1100});await ctx.route('https://**/*',lambda r:r.abort());p=await ctx.new_page();errors=[];p.on('pageerror',lambda e:(errors.append(str(e)),print('JS',str(e),flush=True)))
  await p.add_init_script("window.__legacyHomeSeen=false;new MutationObserver(()=>{if(document.querySelector('#sicip-home-enhancements,#sicip-rewards-home-panel'))window.__legacyHomeSeen=true}).observe(document,{childList:true,subtree:true})")
  async def login(mat):
   await p.goto(HOST+'/login');await p.locator('input[type=text]').first.fill(mat);await p.locator('input[type=password]').fill('PruebaSegura123!');await p.get_by_role('button',name='Iniciar Sesión',exact=True).click();await p.locator('nav.sidebar').wait_for()
  async def api(path,method='GET',d=None):return await p.evaluate('(x)=>window.SICIPCentral.api(x.p,{method:x.m,...(x.d?{body:JSON.stringify(x.d)}:{})})',{'p':path,'m':method,'d':d})
  await login('TESTADMIN');await p.locator('.home-metrics').wait_for();today=(await api('/api/inicio'))['fecha'];folio=(await api('/api/pases/folio','POST',{'request_id':'aaaaaaaa-1111-4111-8111-111111111111'}))['folio'];await api('/api/pases/registros','POST',{'folio':folio,'matricula':'TESTUSER','nombre':'Trabajador prueba','categoria':'Categoría','servicio':'Servicio','fecha':today,'hora':'12:00','tipoAsunto':'PARTICULAR','tipoHorario':'SALIDA','estado':'PENDIENTE_ENTREGA'});await api('/api/personal/incidencias','POST',{'id':'FALTA-HOME-TEST','matricula':'TESTUSER','fecha':today,'observaciones':'Prueba sintética'})
  # Worker loads a fresh document with the slow dashboard response; no old home is ever inserted.
  await api('/api/login','POST',{'matricula':'TESTUSER','password':'PruebaSegura123!'});
  async def slow(route):await asyncio.sleep(.5);await route.continue_()
  await p.route('**/api/inicio',slow);await p.goto(HOST+'/');await p.locator('.home-metrics').wait_for();assert not await p.evaluate('window.__legacyHomeSeen');d=await api('/api/inicio');assert d['resumen']['pases_personales']==1 and d['resumen']['faltas_anio']==1;assert d['aura']['nivel']==5 and d['aura']['puntos']==420
  await p.locator('.aura-celebration').wait_for();assert 'nivel 5' in await p.locator('.aura-celebration').inner_text();await p.locator('.aura-celebration button').click();await p.locator('.aura-celebration').wait_for(state='detached');assert (await api('/api/inicio/avisos'))['avisos']==[];assert await p.locator('[data-home-unread]').inner_text()==str(d['sin_leer']);assert await p.get_by_role('heading',name='Tu constancia cuenta',exact=True).count()==1;assert await p.locator('#sicip-pwa-install,#sicip-pwa-notif').count()==0;print('Inicio sin capa anterior, datos por matrícula, 420 puntos y popup de nivel real comprobados.',flush=True)
  await p.screenshot(path='/workspace/sicip-env/inicio-desktop-543.png',full_page=True)
  # Install must call the native prompt synchronously from an actual user click. Acceptance alone is not installation.
  await p.evaluate("()=>{window.__installCalls=0;const e=new Event('beforeinstallprompt',{cancelable:true});e.prompt=()=>{window.__installCalls++;window.__activeAtInstall=navigator.userActivation.isActive;return Promise.resolve()};e.userChoice=Promise.resolve({outcome:'accepted'});window.dispatchEvent(e)}");await p.locator('[data-install-app]').click();assert await p.evaluate('window.__installCalls')==1;assert await p.evaluate('window.__activeAtInstall');assert 'Esperando confirmación' in await p.locator('[data-install-status]').inner_text();await p.evaluate("window.dispatchEvent(new Event('appinstalled'))");assert await p.locator('[data-install-app]').count()==0;assert 'SICIP ya está instalada' in await p.locator('[data-home-install]').inner_text();print('El botón invoca el diálogo nativo y espera appinstalled para confirmar instalación.',flush=True)
  # Specific search remains in Mis trámites; delivery links carry their filter.
  await p.locator('[data-home-route="/mis-tramites?entrega=pendiente"]').click();await p.locator('[data-tracking-filters]').wait_for();await p.locator('[data-tracking]').get_by_text(folio,exact=True).wait_for();assert await p.locator('[data-delivery]').input_value()=='pendiente';await p.locator('[data-search]').fill('NO-EXISTE');await p.get_by_text('No hay trámites con estos filtros.',exact=True).wait_for();await p.locator('[data-search]').fill(folio);await p.locator('[data-kind]').select_option('PASE');assert '1 de 1' in await p.locator('[data-found]').inner_text()
  await p.locator('nav.sidebar').get_by_role('button',name='Inicio',exact=True).click();await p.locator('.home-metrics').wait_for();assert await p.locator('.aura-celebration').count()==0;assert not await p.evaluate('window.__legacyHomeSeen');await p.set_viewport_size({'width':390,'height':844});assert await p.evaluate('document.documentElement.scrollWidth<=innerWidth+1');await p.screenshot(path='/workspace/sicip-env/inicio-mobile-543.png',full_page=True);assert not errors,errors;await b.close();print('Filtros de historial, retorno sin parpadeo y diseño móvil comprobados.',flush=True)
asyncio.run(main())
